select *
from base_lithology_recognition_result

    f_is_delete = '0'

        and f_create_user_id = #{recognitionresult.fUserId}


        and f_project_section_id = #{recognitionresult.fProjectSectionId}


        and f_section_Id = #{recognitionresult.fSectionId}


        and f_project_section_id = #{recognitionresult.fProjectSectionId}


        and f_section_Id = #{recognitionresult.fSectionId}


        and f_detailed_location = #{recognitionresult.fDetailedLocation}


        and f_create_time >= #{recognitionresult.timeStart}


        and f_create_time <= #{recognitionresult.timeEnd}


        and f_class_name = #{recognitionresult.fClassName}


        and f_scene = #{recognitionresult.fScene}


        and f_mileage_min >= #{recognitionresult.fMileageMinStart}


        and f_mileage_min <= #{recognitionresult.fMileageMinEnd}


        and f_mileage_max >= #{recognitionresult.fMileageMaxStart}


        and f_mileage_max <= #{recognitionresult.fMileageMaxEnd}


        and f_elevation >= #{recognitionresult.fElevationStart}


        and f_elevation <= #{recognitionresult.fElevationEnd}



        and f_longitude >= #{recognitionresult.fLongitudeStart}


        and f_longitude <= #{recognitionresult.fLongitudeEnd}



        and f_latitude >= #{recognitionresult.fLatitudeStart}


        and f_latitude <= #{recognitionresult.fLatitudeEnd}


        and f_provinces = #{recognitionresult.fProvinces}


        and f_cities = #{recognitionresult.fCities}


        and f_districts_counties = #{recognitionresult.fDistrictsCounties}

select *
from base_lithology_recognition_result

    f_is_delete = '0'
    and (f_project_section_id= #{fId} or f_section_Id = #{fId})
    and f_identify_date = #{record}

        and f_create_user_id = #{recognitionresult.fUserId}


        and f_detailed_location like concat('%',#{recognitionresult.fDetailedLocation},'%')





        and (

            f_class_name = trim(#{item})

        )


        and f_scene = #{recognitionresult.fScene}


        and f_mileage_min >= #{recognitionresult.fMileageMinStart}


        and f_mileage_min <= #{recognitionresult.fMileageMinEnd}


        and f_mileage_max >= #{recognitionresult.fMileageMaxStart}


        and f_mileage_max <= #{recognitionresult.fMileageMaxEnd}


        and f_elevation >= #{recognitionresult.fElevationStart}


        and f_elevation <= #{recognitionresult.fElevationEnd}



        and f_longitude >= #{recognitionresult.fLongitudeStart}


        and f_longitude <= #{recognitionresult.fLongitudeEnd}



        and f_latitude >= #{recognitionresult.fLatitudeStart}


        and f_latitude <= #{recognitionresult.fLatitudeEnd}


        and f_provinces = #{recognitionresult.fProvinces}


        and f_cities = #{recognitionresult.fCities}


        and f_districts_counties = #{recognitionresult.fDistrictsCounties}

    order by f_identify_date desc

SELECT blrr.f_identify_date FROM base_lithology_recognition_result blrr WHERE blrr.f_is_delete = 0 and (blrr.f_project_section_id= #{fId} or blrr.f_section_Id = #{fId})
and blrr.f_identify_date >= #{recognitionresult.timeStart}
and blrr.f_identify_date <= #{recognitionresult.timeEnd}
group by blrr.f_identify_date order by blrr.f_identify_date desc
